if (typeof document !== 'undefined') {
  const state = {
    stored: null,
    me: null,
    list: null,
    open: null,
    pending: null,
    view: null,
    stopped: false,
    socketUp: false,
    retryMs: RETRY_FIRST_MS,
    pollTimer: null,
    refreshing: null,
    again: false,
