/// Write one JSON response with `headers` beyond the usual. Head and
/// body in one write, so a reply is one TLS record and one segment.
/// `no-store` and `nosniff` are for a browser, which may read a JSON
/// reply; no native client reads them.
fn respond<W: Write>(
    w: &mut W,
    status: u16,
    body: &[u8],
    headers: &[(&'static str, String)],
) -> io::Result<()> {
    let mut extra = String::from("Cache-Control: no-store\r\nX-Content-Type-Options: nosniff\r\n");
    for (name, value) in headers {
        let _ = write!(extra, "{name}: {value}\r\n");
    }
    write_response(w, status, "application/json", &extra, "keep-alive", body)
}

